<script setup>
import { computed,onMounted,ref } from 'vue'
import { useRoute,onBeforeRouteLeave } from 'vue-router'
import { router } from '../router.js'
import { state,t,bridge,run,clearError } from '../state.js'
import { content,loadContent,ensurePostDraft,dirtyPost,discardPost,applyContent } from '../content-state.js'
import { characterCount,validatePost } from '../domain/content.js'
import { newId } from '../domain/id.js'
import { choices } from '../data/choices.js'
import ContentShell from '../components/ContentShell.vue'
import CollectionEditor from '../components/CollectionEditor.vue'
import ContentMediaPicker from '../components/ContentMediaPicker.vue'
import AppModal from '../components/AppModal.vue'
import ActionButton from '../components/ActionButton.vue'
import AppIcon from '../components/AppIcon.vue'
const route=useRoute(),d=computed(()=>content.draft),sheet=ref(''),editing=ref(null),leaveTarget=ref(null)
let allowLeave=false
onMounted(async()=>{if(!content.loaded)await loadContent({quiet:true});await ensurePostDraft(route.query.from||'/home')})
onBeforeRouteLeave(to=>{if(allowLeave||!dirtyPost()||(to.name==='store'&&to.query.from==='/compose'))return true;leaveTarget.value=to.fullPath;sheet.value='leave';return false})
const valid=computed(()=>{if(!d.value?.ready)return false;try{validatePost(d.value,content.policy);return true}catch{return false}})
const count=computed(()=>characterCount(d.value?.body||'')),collection=computed(()=>content.collections.find(x=>x.id===d.value?.collectionId))
function open(name){editing.value=name==='visibility'?{...d.value.visibility}:name==='audience'?d.value.audienceFilter:d.value.collectionId;sheet.value=name}
function close(){if(state.ui.error==='PRO_LOCKED')clearError();sheet.value='';editing.value=null}
function save(){if(sheet.value==='visibility')d.value.visibility={...editing.value};else if(sheet.value==='audience')d.value.audienceFilter=editing.value;else d.value.collectionId=editing.value;close()}
async function publish(){await run('content-publish',async(signal,done)=>{const draft=d.value,result=await bridge.call('content','publish',{draftId:draft.id,commitId:draft.commitId,...validatePost(draft,content.policy),collectionId:draft.collectionId},{signal});await applyContent(result,signal);content.lastPublishedId=result.resultId;content.feedStartId=null;content.feedScroll=0;const target=draft.visibility.private?'/my-posts':draft.returnPath;content.draft=null;state.ui.notice='p2.published';allowLeave=true;done();await router.replace(target)}, {critical:true})}
async function leave(keep){if(!keep && !await discardPost())return;const target=leaveTarget.value||d.value?.returnPath||'/home';if(keep)state.ui.notice='p2.draftSaved';sheet.value='';allowLeave=true;await router.push(target)}
function back(){router.push(d.value?.returnPath||'/home')}
function create(){sheet.value='create'}

</script>
<template><ContentShell back :ready="!!d?.ready" :title="t('p2.publishTitle')" @back="back"><div v-if="!d?.ready" class="content-state"><p>{{ t('p2.loading') }}</p><ActionButton v-if="!state.ui.busy" @click="ensurePostDraft()">{{ t('retry') }}</ActionButton></div><template v-else><fieldset class="composer-form" :disabled="!!state.ui.busy"><section class="composer-card"><ContentMediaPicker/><label class="sr-only" for="post-body">{{ t('p2.postPlaceholder') }}</label><textarea id="post-body" v-model="d.body" :placeholder="t('p2.postPlaceholder')" :aria-invalid="count>content.policy.bodyLimit"/><p class="character-counter" :class="{invalid:count>content.policy.bodyLimit}">{{ t('p2.characters',{n:count,max:content.policy.bodyLimit}) }}</p></section><p class="field-hint">{{ t('p2.mediaHint') }}</p><div class="composer-settings"><button class="composer-setting" @click="open('collections')"><img src="/images/p2/collections.png" alt=""/><strong>{{ t('p2.collections') }}</strong><span>{{ collection?.name||t('p2.notSelected') }}</span><AppIcon name="arrow" :size="14"/></button><button class="composer-setting" @click="open('audience')"><img src="/images/p2/filters.png" alt=""/><strong>{{ t('p2.filters') }}</strong><span>{{ t('p2.any') }}</span><AppIcon name="arrow" :size="14"/></button><button class="composer-setting" @click="open('visibility')"><img src="/images/p2/visibility.png" alt=""/><strong>{{ t('p2.visibility') }}</strong><span>{{ t('p2.'+(d.visibility.private?'private':d.visibility.audience)) }}</span><AppIcon name="arrow" :size="14"/></button></div><fieldset class="composer-topics"><legend>{{ t('p2.topics') }} <span class="optional">{{ t('optional') }}</span></legend><div class="chips"><button v-for="x in choices.interests" :key="x.id" class="chip" :class="{selected:d.tagIds.includes(x.id)}" :aria-pressed="d.tagIds.includes(x.id)" @click="d.tagIds.includes(x.id)?d.tagIds.splice(d.tagIds.indexOf(x.id),1):d.tagIds.push(x.id)">{{ x[state.locale] }}</button></div></fieldset></fieldset></template><template #footer><p class="quota-caption">{{ t(d?.visibility.private?'p2.privateQuota':content.quota.limit===null?'p2.noQuota':'p2.quota',{n:Math.max(0,content.quota.limit-content.quota.used)}) }}</p><ActionButton class="purple-gradient" :busy="state.ui.busy==='content-publish'" :disabled="!valid||!!state.ui.busy" @click="publish">{{ t('p2.publish') }}</ActionButton></template></ContentShell>
<AppModal v-if="sheet==='visibility'" sheet :title="t('p2.visibility')" @close="close"><label class="setting-option"><span><strong>{{ t('p2.private') }}</strong><small>{{ t('p2.privateHint') }}</small></span><input v-model="editing.private" type="checkbox" role="switch"/></label><h3 class="sheet-section-title">{{ t('p2.appearances') }}</h3><label v-for="id in ['discover','profile']" :key="id" class="setting-option" :class="{muted:editing.private}"><span><strong>{{ t('p2.'+(id==='profile'?'onProfile':id)) }}</strong><small>{{ t('p2.'+(id==='profile'?'onProfileHint':'discoverHint')) }}</small></span><input :checked="!editing.private&&editing[id]" @change="editing[id]=$event.target.checked" type="checkbox" role="switch" :disabled="editing.private"/></label><h3 class="sheet-section-title">{{ t('p2.viewers') }}</h3><label v-for="id in ['everyone','friends']" :key="id" class="setting-option" :class="{muted:editing.private}"><span><strong>{{ t('p2.'+id) }}</strong><small>{{ t('p2.'+(id==='friends'?'friendsDescription':'everyoneDescription')) }}</small></span><input :checked="!editing.private&&editing.audience===id" @change="editing.audience=id" :value="id" name="visibility" type="radio" :disabled="editing.private"/></label><template #headerAction><ActionButton class="purple-gradient sheet-save" @click="save">{{ t('save') }}</ActionButton></template></AppModal>
<AppModal v-if="sheet==='audience'" sheet :title="t('p2.audience')" @close="close"><p class="sheet-hint">{{ t('p2.audienceHint') }}</p><button class="setting-option" @click="editing='any'" aria-pressed="true"><span><strong>{{ t('p2.noGender') }}</strong><small>{{ t('p2.everyoneHint') }}</small></span><AppIcon name="check"/></button><template v-for="(ids,index) in [['men','women'],['excludeMen','excludeWomen']]" :key="index"><h3 class="sheet-section-title">{{ t('p2.'+(index?'exclude':'include')) }} <img src="/images/p2/pro.png" alt="Pro"/></h3><button v-for="id in ids" :key="id" class="setting-option locked-option" disabled aria-disabled="true"><span><strong>{{ t('p2.'+id) }}</strong><small>{{ t('p2.'+id+'Hint') }}</small></span><span class="locked-radio" aria-hidden="true"/></button></template><p class="sheet-hint">{{ t('p2.proLocked') }}</p><button class="text-link" :disabled="!!state.ui.busy" @click="close();router.push('/store?from=/compose')">{{ t('p6.title') }}</button><template #headerAction><ActionButton class="purple-gradient sheet-save" @click="save">{{ t('save') }}</ActionButton></template></AppModal>
<AppModal v-if="sheet==='collections'" sheet :title="t('p2.collections')" @close="close"><div v-if="!content.collections.length" class="collection-empty"><img src="/images/p2/collection-empty.png" alt=""/><h2>{{ t('p2.noCollections') }}</h2><p>{{ t('p2.collectionHint') }}</p></div><button v-else class="option-row" :aria-pressed="editing===null" @click="editing=null">{{ t('p2.noCollection') }}</button><button v-for="x in content.collections" :key="x.id" class="collection-option" :aria-pressed="editing===x.id" @click="editing=x.id"><img v-if="x.coverUrl" :src="x.coverUrl" alt=""/><span><strong>{{ x.name }}</strong><small>{{ x.postIds.length }}</small></span><AppIcon v-if="editing===x.id" name="check"/></button><ActionButton class="purple-gradient" @click="create">{{ t('p2.createCollection') }}</ActionButton><template #headerAction><ActionButton class="purple-gradient sheet-save" @click="save">{{ t('save') }}</ActionButton></template></AppModal>
<CollectionEditor v-if="sheet==='create'" @close="sheet='collections'" @saved="id=>{editing=id;d.collectionId=id;sheet='collections'}"/>
<AppModal v-if="sheet==='leave'" :title="t('p2.leaveTitle')" :closable="!state.ui.busy" @close="close"><p>{{ t('p2.leaveHint') }}</p><div class="source-actions"><ActionButton secondary @click="close">{{ t('p2.continueEditing') }}</ActionButton><ActionButton class="purple-gradient" @click="leave(true)">{{ t('p2.keepDraft') }}</ActionButton><ActionButton quiet :disabled="!!state.ui.busy" @click="leave(false)">{{ t('p2.discard') }}</ActionButton></div></AppModal></template>
